  leadingDetachedComments = _messages.StringField(2, repeated=True)
  path = _messages.IntegerField(3, repeated=True, variant=_messages.Variant.INT32)
  span = _messages.IntegerField(4, repeated=True, variant=_messages.Variant.INT32)
  trailingComments = _messages.StringField(5)


