    ST_RESERVED_12012 = 12
    ST_RESERVED_12013 = 13
    ST_RESERVED_12014 = 14
    ST_RESERVED_12015 = 15
    ST_RESERVED_12016 = 16
    ST_RESERVED_12017 = 17
    ST_RESERVED_12018 = 18
    ST_RESERVED_12019 = 19
    ST_RESERVED_12020 = 20
    ST_RESERVED_12021 = 21
    ST_RESERVED_12022 = 22
    ST_RESERVED_12023 = 23
    ST_RESERVED_12024 = 24
    ST_RESERVED_12025 = 25
    ST_RESERVED_12026 = 26
    ST_RESERVED_12027 = 27
    ST_RESERVED_12028 = 28
    ST_RESERVED_12029 = 29
    ST_RESERVED_12030 = 30
