  environment = _messages.EnumField('EnvironmentValueValuesEnum', 2)
  grantsAccessToMpaProtectedEndpointOnly = _messages.BooleanField(3)
  grantsInnocuousWriteAccessOnly = _messages.BooleanField(4)
  grantsReadAccessOnly = _messages.BooleanField(5)
  impactedTeamProductId = _messages.IntegerField(6, repeated=True)
  reason = _messages.MessageField('PrivacyDataGovernanceAttributesProductionImpact', 7)


